print('all inter-fragment close pairs <1.5')
groups={'Cp':range(7,32),'Ar':range(32,61),'Ph1':range(61,72),'Ph2':range(72,83),'Core':range(0,7)}
for name,g in groups.items():
 for name2,h in groups.items():
  if list(groups).index(name2)<=list(groups).index(name):continue
  pairs=[]
  for i in g:
   for j in h:
    d=np.linalg.norm(r[i]-r[j])
    if d<1.5:pairs.append((round(d,2),i,j,a[i],a[j]))
  if pairs:print(name,name2,pairs)
print('atom count',len(a),'lines',len(open('answer.xyz').read().splitlines()))
